window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[307]={"id":"307","numero":307,"titre":"Tumeurs des os, primitives et secondaires","objectifs":[{"id":"307-1","rang":"A","rubrique":"Définition","titre":"Connaître les différents familles de tumeurs osseuses (primitive, secondaire)","contenu":"<p>Deux grandes familles de tumeurs osseuses, distinguées par leur <span class=\"kw-def\"><strong>origine cellulaire</strong></span> :</p>\n      <ul>\n        <li><span class=\"kw-def\"><strong>Tumeurs primitives</strong></span> : développées à partir des différents <span class=\"kw-def\">tissus de l'appareil ostéoarticulaire</span> (os, cartilage, conjonctif, hématopoïétique, embryonnaire). Les sarcomes osseux primitifs sont <span class=\"kw-chiffre\">rares</span> (~ <span class=\"kw-chiffre\">500 nouveaux cas/an</span> en France), avec une prédominance masculine (sex-ratio <span class=\"kw-chiffre\">1,5 H/F</span>).</li>\n        <li><span class=\"kw-def\"><strong>Tumeurs secondaires</strong></span> = <span class=\"kw-etio\">métastases osseuses</span> d'un cancer primitif extra-osseux (sein, prostate, poumon, rein, thyroïde…).</li>\n      </ul>\n\n      <div class=\"callout callout-info\"><strong>À retenir — règle de fréquence selon l'âge.</strong>\n        <ul>\n          <li>Chez l'<span class=\"kw-clinique\"><strong>enfant, l'adolescent et l'adulte jeune</strong></span> : une tumeur osseuse maligne est le plus souvent <strong>primitive</strong>.</li>\n          <li>Chez l'<span class=\"kw-clinique\"><strong>adulte &gt; 50 ans</strong></span> : les <strong>métastases osseuses</strong> sont largement prédominantes.</li>\n        </ul>\n      </div>\n\n      <p><strong>Classification par tissu d'origine (tumeurs primitives) :</strong></p>\n      <table >\n        <thead><tr><th>Tissu d'origine</th><th>Bénin</th><th>Malin</th></tr></thead>\n        <tbody>\n          <tr>\n            <th>Os</th>\n            <td><span class=\"kw-def\">Ostéome ostéoïde</span> ; <span class=\"kw-def\">Ostéoblastome</span></td>\n            <td><span class=\"kw-etio\"><strong>Ostéosarcome</strong></span> — la plus fréquente <strong>chez l'enfant</strong></td>\n          </tr>\n          <tr>\n            <th>Cartilage</th>\n            <td><span class=\"kw-def\">Chondrome / Enchondrome</span> ; Exostose ostéogénique ; <span class=\"kw-def\">Ostéochondrome</span></td>\n            <td><span class=\"kw-etio\"><strong>Chondrosarcome</strong></span> — la plus fréquente <strong>chez l'adulte</strong></td>\n          </tr>\n          <tr>\n            <th>Conjonctif</th>\n            <td>Fibrome non ossifiant ; Fibrome myxoïde / chondromyxoïde ; <span class=\"kw-def\">Tumeurs à cellules géantes (TCG)</span></td>\n            <td>Fibrosarcome ; Histiocytofibrome malin</td>\n          </tr>\n          <tr>\n            <th>Hématopoïétique</th>\n            <td>—</td>\n            <td><span class=\"kw-etio\"><strong>Plasmocytome</strong></span> ; <span class=\"kw-etio\">Lymphome osseux</span></td>\n          </tr>\n          <tr>\n            <th>Embryonnaire</th>\n            <td>—</td>\n            <td><span class=\"kw-etio\"><strong>Sarcome d'Ewing</strong></span> (neurectoderme) — 2<sup>e</sup> plus fréquente chez l'enfant ; <span class=\"kw-etio\">Chordome</span> (notochorde, surtout sacrum)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong>Malignité « intermédiaire ».</strong> <span class=\"kw-def\">Chordomes</span> et <span class=\"kw-def\">tumeurs à cellules géantes des os</span> (anciennement « tumeurs à ostéoclastes ») se présentent comme des tumeurs malignes, avec un <span class=\"kw-alerte\">risque d'évolution surtout locale</span> et <strong>rarement métastatique</strong>.</div>\n\n      <p><strong>Facteurs de risque de tumeur osseuse primitive :</strong></p>\n      <table >\n        <thead><tr><th>Facteur de risque</th><th>Risque tumoral</th></tr></thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-etio\">Radiothérapie antérieure</span></th>\n            <td>Cancer osseux possible <span class=\"kw-chiffre\">4 à 20 ans</span> après ; &lt; <span class=\"kw-chiffre\">1 %</span> des cas</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\">Maladie de Paget</span></th>\n            <td>Transformation en <span class=\"kw-etio\"><strong>ostéosarcome</strong></span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\">Infarctus osseux</span> ; fractures avec <span class=\"kw-alerte\">matériel orthopédique</span></th>\n            <td>Risque accru de sarcome osseux secondaire</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\"><strong>Li-Fraumeni</strong></span> (mutation germinale <em>p53</em>)</th>\n            <td>→ <span class=\"kw-etio\"><strong>ostéosarcome</strong></span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\"><strong>Rétinoblastome familial</strong></span> (gène <em>Rb</em>)</th>\n            <td>→ <span class=\"kw-etio\"><strong>ostéosarcome</strong></span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\">Exostoses multiples</span> ; <span class=\"kw-etio\">maladie d'Ollier</span> (enchondromes multiples)</th>\n            <td>→ <span class=\"kw-etio\"><strong>chondrosarcome</strong></span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers · 320 — Myélome multiple des os</em></p>","frequence":3},{"id":"307-2","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les circonstances de découverte, les manifestations cliniques et radiologiques des tumeurs osseuses","contenu":"<p><strong>Circonstances de découverte et manifestations cliniques :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\"><strong>Douleur osseuse</strong></span> : soit <span class=\"kw-clinique\">inflammatoire</span> (extension tumorale, horaire nocturne, ne calmée pas par le repos), soit <span class=\"kw-clinique\">mécanique/mixte</span> (fissure ou fracture pathologique).</li>\n        <li><span class=\"kw-clinique\"><strong>Tuméfaction</strong></span> osseuse ou des parties molles adjacentes, <strong>sans facteur traumatique déclenchant</strong>.</li>\n        <li><span class=\"kw-clinique\">Impotence fonctionnelle</span> ; <span class=\"kw-clinique\">boiterie</span>.</li>\n        <li><span class=\"kw-clinique\">Signes de compression nerveuse</span> : radiculalgie, compression médullaire (tumeurs vertébrales).</li>\n        <li>Découverte de <span class=\"kw-clinique\"><strong>fracture pathologique</strong></span> spontanée ou après traumatisme minime.</li>\n        <li>Chez l'enfant en croissance : <span class=\"kw-clinique\">inégalité de longueur</span> ou déformation acquise.</li>\n        <li><span class=\"kw-alerte\">AEG + fièvre</span> rares mais possibles : surtout <strong>sarcome d'Ewing</strong> (diagnostic différentiel = ostéomyélite).</li>\n      </ul>\n\n      <div class=\"callout callout-danger\"><strong>Piège classique — traumatisme minime trompeur.</strong>\n        Ne <span class=\"kw-alerte\">jamais</span> se laisser piéger par un traumatisme minime présenté comme causal par le patient ou sa famille : la tumeur <strong>préexistait</strong>, le choc n'a fait que la révéler (fracture pathologique).\n      </div>\n\n      <p><strong>Critères radiologiques de bénignité vs malignité (tableau de référence EDN) :</strong></p>\n      <table >\n        <thead><tr><th>Critère</th><th>En faveur d'une <strong>bénignité</strong></th><th>En faveur d'une <strong>malignité</strong></th></tr></thead>\n        <tbody>\n          <tr>\n            <th>Clinique</th>\n            <td>\n              <strong>Évolution :</strong> <span class=\"kw-clinique\">lente</span><br>\n              <strong>Douleur :</strong> absente ; <span class=\"kw-clinique\">mécanique</span> si présente<br>\n              <strong><span class=\"kw-clinique\">AEG</span> :</strong> absente\n            </td>\n            <td>\n              <strong>Évolution :</strong> rapide<br>\n              <strong>Douleur :</strong> <span class=\"kw-alerte\">inflammatoire</span> ; intensité croissante<br>\n              <strong>Signes :</strong> <span class=\"kw-clinique\">compression nerveuse</span> (médullaire, radiculaire, tronculaire) ; <span class=\"kw-clinique\">AEG rare</span> sauf <strong>Ewing</strong>\n            </td>\n          </tr>\n          <tr>\n            <th>Biologie</th>\n            <td>Pas d'anomalie associée</td>\n            <td><span class=\"kw-def\">Syndrome inflammatoire</span> (<span class=\"kw-bio\">CRP</span>, <span class=\"kw-bio\">VS</span>) ; <span class=\"kw-bio\"><strong>hypercalcémie</strong></span></td>\n          </tr>\n          <tr>\n            <th>Limites (RX)</th>\n            <td><span class=\"kw-radio\">Nettes</span> ; <span class=\"kw-radio\">liseré condensé périphérique</span></td>\n            <td><span class=\"kw-radio\">Floues</span> — aspect « <span class=\"kw-radio\">mité</span> » ou « <span class=\"kw-radio\">vermoulu</span> »</td>\n          </tr>\n          <tr>\n            <th>Corticales</th>\n            <td>Respectées</td>\n            <td>Rompues ou érodées</td>\n          </tr>\n          <tr>\n            <th>Périoste</th>\n            <td>Non visible ; ou <span class=\"kw-radio\">apposition périostée unilamellaire</span></td>\n            <td>\n              <strong>Triangle / Éperon de Codman</strong> = décollement périosté<br>\n              <span class=\"kw-radio\">Spicules « feu d'herbe »</span> = ostéosarcome ++<br>\n              <span class=\"kw-radio\">Plurilamellaire « bulbe d'oignon »</span> = sarcome d'Ewing ++\n            </td>\n          </tr>\n          <tr>\n            <th>Parties molles</th>\n            <td>Normales</td>\n            <td><span class=\"kw-alerte\">Tuméfaction</span> ; ossifications / calcifications par envahissement</td>\n          </tr>\n          <tr>\n            <th>Nombre</th>\n            <td>—</td>\n            <td><span class=\"kw-alerte\">Lésions multiples</span> évocatrices de malignité (exceptions : ostéochondromes, enchondromes)</td>\n          </tr>\n          <tr>\n            <th>Vertèbres (suspect)</th>\n            <td>—</td>\n            <td>\n              <strong>Localisation :</strong> fracture-tassement <span class=\"kw-alerte\">au-dessus de T5</span><br>\n              <strong>Pédicule :</strong> non visualisé sur RX de face = <span class=\"kw-alerte\">« vertèbre borgne »</span><br>\n              <strong>Symétrie :</strong> fracture asymétrique hors zone de scoliose<br>\n              <strong>Mur postérieur :</strong> déformation / bombement / rupture<br>\n              <strong>Trame :</strong> hétérogénéité\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>QCM-killer EDN — fracture vertébrale au-dessus de T4.</strong>\n        Au-dessus de <span class=\"kw-chiffre\"><strong>T4</strong></span>, il n'y a <span class=\"kw-alerte\">pas d'ostéoporose physiologique significative</span> : toute fracture-tassement dans cette zone est <strong>hautement suspecte d'étiologie maligne</strong>. À l'inverse, fracture en dessous de T7 = <span class=\"kw-def\">ostéoporose</span> plus probable.\n      </div>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>Skip métastase</strong> — devant toute suspicion de tumeur osseuse primitive, l'<span class=\"kw-imagerie\">IRM</span> doit analyser <strong>la totalité de l'os</strong> à la recherche d'une métastase à distance sur le même os (« skip métastase »), notamment dans l'<strong>ostéosarcome</strong> et le <strong>sarcome d'Ewing</strong>.\n      </div>\n\n      <p><strong>Extension à connaître :</strong></p>\n      <ul>\n        <li>Les sarcomes osseux <span class=\"kw-alerte\">n'envahissent pratiquement jamais les aires ganglionnaires</span>.</li>\n        <li>Les métastases <strong>de</strong> tumeurs osseuses primitives sont <span class=\"kw-alerte\">exceptionnellement révélatrices</span>.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 134 — Bases neurophysiologiques de la douleur</em></p>","frequence":2},{"id":"307-3","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître le bilan biologique à pratiquer devant une suspicion de tumeur osseuse","contenu":"<p>Le bilan biologique est peu spécifique mais incontournable : il prépare l'imagerie injectée et la <span class=\"kw-bio\">biopsie</span>, oriente vers les diagnostics différentiels et participe au bilan d'extension.</p>\n\n      <table >\n        <thead><tr><th>Type</th><th>Examen</th><th>Indication / Justification</th></tr></thead>\n        <tbody>\n          <tr>\n            <th rowspan=\"2\">Biologie minimale (systématique)</th>\n            <td><span class=\"kw-bio\"><strong>Fonction rénale</strong></span> (créatininémie + <span class=\"kw-bio\">DFG</span>)</td>\n            <td>Pré-injection de <span class=\"kw-imagerie\">produit de contraste iodé</span> (<span class=\"kw-imagerie\">TDM</span> injectée)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Hémostase</strong></span> : NFS-plaquettes, <span class=\"kw-bio\">TP</span>/<span class=\"kw-bio\">INR</span>, <span class=\"kw-bio\">TCA</span></td>\n            <td>Pré-<strong><span class=\"kw-bio\">biopsie</span></strong> osseuse (saignement)</td>\n          </tr>\n          <tr>\n            <th rowspan=\"4\">Biologie selon le contexte</th>\n            <td><span class=\"kw-bio\"><strong>PAL</strong></span>, transaminases (<span class=\"kw-bio\">ASAT</span>/<span class=\"kw-bio\">ALAT</span>), <span class=\"kw-bio\"><strong>LDH</strong></span>, γGT</td>\n            <td>Élévation possible de <strong><span class=\"kw-bio\">PAL</span></strong> et <strong><span class=\"kw-bio\">LDH</span></strong> dans le sarcome osseux (en l'absence d'atteinte hépatique)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\"><strong>Calcémie</strong></span></td>\n            <td>\n              <strong>Primitives :</strong> <span class=\"kw-alerte\">hypercalcémie exceptionnelle</span> ❌<br>\n              <strong>Secondaires :</strong> hypercalcémie <span class=\"kw-alerte\">fréquente</span> (à dépister systématiquement)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">CRP</span></td>\n            <td>Diagnostic différentiel : <span class=\"kw-etio\">ostéite</span> / <span class=\"kw-etio\">ostéomyélite</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">EPS + immunoélectrophorèse</span> ± <span class=\"kw-bio\">protéinurie</span></td>\n            <td>Recherche <strong>myélome</strong> devant lésion lytique ++ (cf. item 320)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong>Interdiction absolue — aucun marqueur tumoral.</strong>\n        <span class=\"kw-alerte\"><strong>Aucun dosage de marqueur tumoral</strong></span> n'est utile dans les tumeurs osseuses primitives, <strong>ni en diagnostic ni en pronostic</strong>. Exceptions ciblées (cf. <em>obj-6</em> sur métastase inaugurale) : <span class=\"kw-bio\">PSA</span> systématique chez l'homme, <span class=\"kw-bio\">α-fœtoprotéine / β-hCG</span> chez le sujet jeune (testicule).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 320 — Myélome multiple des os</em></p>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/ameloblastoma","label":"Radiopaedia : Ameloblastoma"},{"href":"https://radiopaedia.org/articles/bone-tumors-overview","label":"Radiopaedia : Bone tumors overview"},{"href":"https://radiologyassistant.nl/musculoskeletal/bone-tumors","label":"Bone tumors"},{"href":"https://radiopaedia.org/articles/osteosarcoma","label":"Radiopaedia : Osteosarcoma"},{"href":"https://radiopaedia.org/articles/ewing-sarcoma","label":"Radiopaedia : Ewing sarcoma"},{"href":"https://radiopaedia.org/articles/non-ossifying-fibroma-1","label":"Radiopaedia : Non ossifying fibroma 1"},{"href":"https://radiopaedia.org/articles/exostosis","label":"Radiopaedia : Exostosis"},{"href":"https://radiopaedia.org/articles/enchondroma","label":"Radiopaedia : Enchondroma"},{"href":"https://radiopaedia.org/articles/osteoid-osteoma","label":"Radiopaedia : Osteoid osteoma"},{"href":"https://radiopaedia.org/articles/fibrous-dysplasia","label":"Radiopaedia : Fibrous dysplasia"},{"href":"https://radiopaedia.org/articles/chondroblastoma","label":"Radiopaedia : Chondroblastoma"},{"href":"https://radiopaedia.org/articles/giant-cell-tumour-of-bone","label":"Radiopaedia : Giant cell tumour of bone"},{"href":"https://radiopaedia.org/articles/chondrosarcoma","label":"Radiopaedia : Chondrosarcoma"},{"href":"https://radiopaedia.org/articles/primary-bone-lymphoma","label":"Radiopaedia : Primary bone lymphoma"},{"href":"https://radiopaedia.org/articles/solitary-bone-plasmacytoma-1","label":"Radiopaedia : Solitary bone plasmacytoma 1"},{"href":"https://radiopaedia.org/articles/chordoma","label":"Radiopaedia : Chordoma"},{"href":"https://radiopaedia.org/articles/bone-metastases-1","label":"Radiopaedia : Bone metastases 1"}]},{"id":"307-4","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principaux examens d’imagerie à pratiquer devant une suspicion de tumeur osseuse","contenu":"<p>L'imagerie suit une <span class=\"kw-imagerie\">stratégie hiérarchisée</span> : <strong>RX face + profil</strong> en première intention, puis caractérisation et bilan d'extension. La <strong><span class=\"kw-bio\">biopsie</span> reste indispensable</strong> à la confirmation diagnostique — aucun examen d'imagerie ne s'y substitue.</p>\n\n      <table >\n        <thead><tr><th>Examen</th><th>Indication</th><th>Recherche</th><th>Piège / Limite</th></tr></thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-imagerie\"><strong>RX face + profil</strong></span></th>\n            <td><strong>1<sup>er</sup> examen — systématique et incontournable</strong></td>\n            <td>\n              <strong>Modifications structurales :</strong> ostéolyse ; ostéocondensation ; aspect mixte ; <span class=\"kw-radio\">périoste décollé</span><br>\n              <strong>Limites :</strong> nettes vs floues ; rupture corticale<br>\n              <strong>Périoste :</strong> Codman ; feu d'herbe ; bulbe d'oignon<br>\n              <strong>Fracture pathologique</strong> spontanée\n            </td>\n            <td>Aucun signe spécifique pour la <strong>nature histologique</strong> — <span class=\"kw-bio\">biopsie</span> obligatoire</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-imagerie\"><strong>IRM (T1, T2, T1+gado)</strong></span></th>\n            <td>Caractérisation locorégionale + extension</td>\n            <td>\n              <strong>Matrice :</strong> ossifiante, cartilagineuse, kystique, graisseuse<br>\n              <strong>Extension :</strong> parties molles, vasculo-nerveuse, cartilage de croissance, intra-articulaire<br>\n              <strong>Os entier :</strong> recherche <span class=\"kw-alerte\"><strong>skip métastase</strong></span> sur le même os ++<br>\n              <strong>Vertèbres :</strong> risque de compression médullaire\n            </td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-imagerie\"><strong>TDM injectée (TDM-TAP)</strong></span></th>\n            <td>Caractérisation osseuse + bilan d'extension métastatique</td>\n            <td>\n              <strong>Os :</strong> rupture corticale ; appositions périostées ; type de matrice<br>\n              <strong>Parties molles :</strong> envahissement<br>\n              <strong>Thorax / abdomen / pelvis :</strong> <span class=\"kw-imagerie\">métastases pulmonaires</span> et viscérales<br>\n              <strong>Rachis métastatique :</strong> instabilité\n            </td>\n            <td>Nécessite fonction rénale OK pour injection iodée</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-imagerie\"><strong>Scintigraphie osseuse Tc<sup>99m</sup></strong></span> (± couplée SPECT-<span class=\"kw-imagerie\">TDM</span>)</th>\n            <td>Bilan d'extension osseuse à distance</td>\n            <td>\n              <strong>Hyperfixations multiples</strong> orientant vers un processus métastatique<br>\n              <strong>Couplage <span class=\"kw-imagerie\">TDM</span></strong> = analyse plus précise des anomalies\n            </td>\n            <td><span class=\"kw-alerte\"><strong>Faux négatifs</strong></span> sur lésions très <strong>ostéolytiques pures</strong> : <span class=\"kw-alerte\">myélome ++</span></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-imagerie\"><strong>TEP-TDM (<sup>18</sup>F-FDG)</strong></span></th>\n            <td>Bilan d'extension complet ; alternative à la <span class=\"kw-imagerie\">scintigraphie</span> + <span class=\"kw-imagerie\">TDM</span>-TAP</td>\n            <td>Métastases osseuses <strong>et</strong> extra-osseuses en un seul examen ; remplace le SPECT-<span class=\"kw-imagerie\">TDM</span> dans certains centres</td>\n            <td>—</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>Skip métastase à chercher systématiquement.</strong>\n        L'<span class=\"kw-imagerie\">IRM</span> doit explorer <strong>la totalité de la pièce osseuse atteinte</strong> pour ne pas méconnaître une <strong>localisation à distance sur le même os</strong> (« skip métastase »), notamment dans l'<strong>ostéosarcome</strong> et le <strong>sarcome d'Ewing</strong>. Cette donnée modifie la stratégie chirurgicale.\n      </div>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>Faux négatif scintigraphique.</strong>\n        Une <span class=\"kw-imagerie\">scintigraphie Tc<sup>99m</sup></span> peut être <span class=\"kw-alerte\">faussement négative</span> sur des lésions <strong>très lytiques pures</strong> (<span class=\"kw-alerte\">myélome ++</span>). Devant un tableau évocateur de myélome ou de métastase lytique, recourir à une <span class=\"kw-imagerie\">IRM corps entier</span> et/ou une <span class=\"kw-imagerie\">TEP-FDG</span>.\n      </div>\n\n      <p><strong>Cas particulier — exploration ostéomédullaire :</strong> dans le <strong>sarcome d'Ewing</strong>, ajouter un <span class=\"kw-bio\">myélogramme</span> et une <span class=\"kw-bio\">BOM</span> (<span class=\"kw-bio\">biopsie</span> ostéomédullaire) à la recherche d'un envahissement médullaire.</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 320 — Myélome multiple des os</em></p>","frequence":3},{"id":"307-5","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités d’orientation d’un patient vers une prise en charge spécialisée","contenu":"<p>Devant toute suspicion de tumeur osseuse primitive, le patient doit être <span class=\"kw-clinique\"><strong>adressé sans délai</strong></span> à un centre spécialisé. <span class=\"kw-alerte\">Aucun traitement</span> (et surtout aucun geste orthopédique) ne doit précéder le diagnostic anatomopathologique.</p>\n\n      <table >\n        <thead><tr><th>Étape</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <th>Orientation</th>\n            <td>Centre de référence du réseau <span class=\"kw-clinique\"><strong>NETSARC+</strong></span>, qui organise les <span class=\"kw-clinique\">RCP</span> (réseau labellisé par l'<strong>INCa</strong>).</td>\n          </tr>\n          <tr>\n            <th>Indication de <span class=\"kw-bio\">biopsie</span></th>\n            <td>\n              <strong><span class=\"kw-bio\">Biopsie</span> systématique</strong> avant tout traitement<br>\n              <strong>Pas de traitement</strong> sans diagnostic <span class=\"kw-clinique\">anatomopathologique</span><br>\n              <strong>Décision multidisciplinaire</strong> en RCP avant le geste\n            </td>\n          </tr>\n          <tr>\n            <th>Qui réalise ?</th>\n            <td>Idéalement, l'<span class=\"kw-clinique\"><strong>équipe chirurgicale</strong></span> qui réalisera ensuite l'exérèse carcinologique (continuité du trajet biopsique → trajet d'exérèse).</td>\n          </tr>\n          <tr>\n            <th>Voie</th>\n            <td>\n              <strong>Percutanée :</strong> sous contrôle radiographique ou scanographique<br>\n              <strong>Chirurgicale :</strong> standard = <span class=\"kw-clinique\">biopsie chirurgicale</span>\n            </td>\n          </tr>\n          <tr>\n            <th>Analyses</th>\n            <td>\n              <strong>Histologique :</strong> nécessite une <span class=\"kw-clinique\">décalcification</span> + <span class=\"kw-clinique\">immunomarquage</span><br>\n              <strong>Bactériologique :</strong> germes banals + mycobactéries (diagnostic différentiel ostéite)<br>\n              <strong>Moléculaire :</strong> <span class=\"kw-clinique\"><strong>biopsie à l'état frais</strong></span> obligatoire pour <strong>FISH / <span class=\"kw-bio\">PCR</span></strong> (translocation t(11;22) Ewing ++)\n            </td>\n          </tr>\n          <tr>\n            <th>Confirmation</th>\n            <td><span class=\"kw-clinique\"><strong>2<sup>e</sup> lecture histologique</strong></span> systématique par un expert d'un centre de référence (INCa) — tumeurs rares à haut risque d'erreur diagnostique.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong>Interdiction absolue — enclouage et matériel orthopédique.</strong>\n        <span class=\"kw-alerte\"><strong>L'enclouage</strong></span> ou la mise en place de <span class=\"kw-alerte\">matériel orthopédique (vis, plaque)</span> sur un os fracturé suspect de tumeur osseuse primitive est <strong>absolument <span class=\"kw-ci\">proscrit</span></strong> : il <span class=\"kw-alerte\">contamine</span> l'os entier et expose à :\n        <ul>\n          <li>Rechute locale</li>\n          <li><span class=\"kw-alerte\">Amputation ou désarticulation</span> chez un patient qui aurait pu bénéficier d'un <strong><span class=\"kw-ttt\">traitement conservateur du membre</span></strong></li>\n        </ul>\n        Devant toute fracture suspecte, immobilisation simple + RX + <span class=\"kw-imagerie\">IRM</span> + adressage <strong>NETSARC+</strong>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 294 — Traitement des cancers · 295 — Prise en charge d'un malade cancéreux</em></p>","frequence":1},{"id":"307-6","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les cancers qui sont le plus fréquemment responsable des métastases osseuses et les circonstances de découverte","contenu":"<p>Toute néoplasie peut métastaser à l'os, mais 5 primitifs concentrent l'essentiel des métastases osseuses. Mnémo officiel : <span class=\"kw-def\"><strong>PPRST</strong></span> (Prostate, Poumon, Rein, Sein, Thyroïde).</p>\n\n      <table >\n        <thead><tr><th>Primitif</th><th>Aspect radiologique</th><th>Particularité</th></tr></thead>\n        <tbody>\n          <tr>\n            <th><span class=\"kw-etio\"><strong>Sein</strong></span></th>\n            <td><span class=\"kw-radio\">Lytique</span> ou <span class=\"kw-radio\">mixte</span></td>\n            <td><strong>1<sup>er</sup> primitif</strong> en fréquence absolue de métastases osseuses</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\"><strong>Prostate</strong></span></th>\n            <td><span class=\"kw-radio\"><strong>Ostéocondensant</strong></span> +++ (mais <span class=\"kw-chiffre\">25 %</span> de formes lytiques)</td>\n            <td>Mémo : la seule métastase franchement <strong>condensante</strong></td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\"><strong>Poumon</strong></span></th>\n            <td><span class=\"kw-radio\">Lytique</span> ; <span class=\"kw-radio\">corticales</span> ; <span class=\"kw-imagerie\">doigts / orteils</span></td>\n            <td>Localisations distales typiques (acrométastases)</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\"><strong>Rein</strong></span></th>\n            <td><span class=\"kw-radio\">Lytique pur</span>, souvent <span class=\"kw-radio\">soufflante</span> et hypervascularisée</td>\n            <td>Risque <span class=\"kw-etio\">hémorragique</span> à la <span class=\"kw-bio\">biopsie</span> (<span class=\"kw-ttt\">embolisation</span> préalable)</td>\n          </tr>\n          <tr>\n            <th><span class=\"kw-etio\"><strong>Thyroïde</strong></span></th>\n            <td><span class=\"kw-radio\">Lytique pur</span></td>\n            <td>Place de l'<strong><span class=\"kw-ttt\">iode radioactif</span></strong> en traitement métabolique</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Ordre de fréquence (à connaître pour les QCM EDN) :</strong> <span class=\"kw-etio\">sein</span> &gt; <span class=\"kw-etio\">prostate</span> &gt; <span class=\"kw-etio\">poumon</span> &gt; <span class=\"kw-etio\">rein</span> &gt; <span class=\"kw-etio\">thyroïde</span> &gt; vessie &gt; mélanome.</p>\n\n      <div class=\"callout callout-info\"><strong>Chez l'enfant.</strong> Le <span class=\"kw-etio\"><strong>neuroblastome</strong></span> est le principal pourvoyeur de métastases osseuses.</div>\n\n      <p><strong>Topographie des métastases osseuses (ordre de fréquence) :</strong></p>\n      <ol>\n        <li><span class=\"kw-clinique\">Rachis lombaire</span>, rachis thoracique</li>\n        <li>Bassin ; côtes ; sternum ; fémurs ; humérus ; crâne</li>\n        <li>Métastases <strong>distales</strong> rares (mais évocatrices du poumon)</li>\n      </ol>\n\n      <p><strong>Circonstances de découverte :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\"><strong>Bilan d'extension</strong></span> ou <span class=\"kw-clinique\">surveillance d'un cancer connu</span></li>\n        <li><span class=\"kw-clinique\"><strong>Découverte fortuite</strong></span> révélant la maladie cancéreuse (« métastase osseuse inaugurale »)</li>\n        <li>Bilan d'une <span class=\"kw-bio\"><strong>hypercalcémie</strong></span></li>\n        <li><span class=\"kw-clinique\"><strong>Syndrome rachidien majeur</strong></span> : douleurs rachidiennes <span class=\"kw-alerte\">inflammatoires</span>, <span class=\"kw-clinique\">radiculalgie</span></li>\n        <li><span class=\"kw-alerte\">Troubles neurologiques</span> par compression médullaire ou radiculaire (<span class=\"kw-chiffre\">5–20 %</span> des cas)</li>\n        <li><span class=\"kw-alerte\"><strong>Fracture pathologique</strong></span> spontanée ou sur traumatisme minime</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ <strong><span class=\"kw-chiffre\">10 %</span> de primitif non retrouvé.</strong>\n        Au terme du bilan étiologique, le cancer primitif reste <strong>méconnu dans environ <span class=\"kw-chiffre\">10 %</span></strong> des métastases osseuses inaugurales. La stratégie thérapeutique se discute alors selon l'aspect IHC et le profil métastatique en RCP.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers</em></p>","frequence":2},{"id":"307-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principaux éléments de l’enquête étiologique devant une métastase osseuse inaugurale","contenu":"<p>Devant une métastase osseuse <strong>révélatrice</strong> d'un cancer non encore connu, l'enquête étiologique combine : orientation radiologique, biologie ciblée, marqueurs tumoraux dans des indications précises, imagerie hiérarchisée et <span class=\"kw-bio\">biopsie</span> en dernier recours (priorité à la tumeur primitive).</p>\n\n      <table >\n        <thead><tr><th>Axe</th><th>Démarche</th></tr></thead>\n        <tbody>\n          <tr>\n            <th>Selon l'aspect radiologique</th>\n            <td>\n              <strong>Ostéocondensant :</strong> <span class=\"kw-etio\">prostate</span> +++ (mais <span class=\"kw-chiffre\">25 %</span> de formes lytiques)<br>\n              <strong>Ostéolytique :</strong> <span class=\"kw-etio\">rein</span> ; <span class=\"kw-etio\">thyroïde</span> ; <span class=\"kw-etio\">sein</span> ; <span class=\"kw-etio\">poumon</span><br>\n              <strong>Mixte :</strong> <span class=\"kw-etio\">sein</span>, <span class=\"kw-etio\">poumon</span><br>\n              <strong>Corticales :</strong> <span class=\"kw-etio\">poumon</span><br>\n              <strong>Doigts / orteils :</strong> <span class=\"kw-etio\">poumon</span> (acrométastases)\n            </td>\n          </tr>\n          <tr>\n            <th>Biologie</th>\n            <td>\n              <strong><span class=\"kw-bio\">NFS</span>, bilan phosphocalcique</strong> (<span class=\"kw-bio\">calcémie</span> + <span class=\"kw-bio\">albuminémie</span>)<br>\n              <strong>Syndromes paranéoplasiques :</strong> dosages orientés (souvent poumon)<br>\n              <strong>Myélome (systématique) :</strong> <span class=\"kw-bio\"><strong>EPS</strong></span>, immunoélectrophorèse, <span class=\"kw-bio\">protéinurie</span> ± médullogramme\n            </td>\n          </tr>\n          <tr>\n            <th>Marqueurs tumoraux</th>\n            <td>\n              <span class=\"kw-bio\"><strong>PSA</strong></span> : <strong>systématique chez l'homme</strong> (sensible et très spécifique &gt; <span class=\"kw-chiffre\">15 ng/mL</span>)<br>\n              <span class=\"kw-bio\">α-FP / β-hCG</span> : chez le <strong>sujet jeune</strong> → tumeur germinale non séminomateuse du testicule\n            </td>\n          </tr>\n          <tr>\n            <th>Imagerie de 1<sup>re</sup> intention</th>\n            <td>\n              <strong>1.</strong> <span class=\"kw-imagerie\"><strong>RX thoracique</strong></span> + <span class=\"kw-imagerie\">mammographie</span> chez la femme<br>\n              <strong>2.</strong> <span class=\"kw-imagerie\"><strong>TDM-TAP injectée</strong></span><br>\n              <strong>3.</strong> <span class=\"kw-imagerie\">TEP au <sup>18</sup>F-FDG</span> en cas de <span class=\"kw-imagerie\">TDM</span> négatif<br>\n              <strong>4.</strong> <span class=\"kw-imagerie\">IRM du rachis complet</span> au moindre signe d'appel (ostéolytique hypoT1/hyperT2, ostéocondensant hypoT1/hypoT2)\n            </td>\n          </tr>\n          <tr>\n            <th>Place de la <span class=\"kw-bio\">biopsie</span></th>\n            <td>\n              <strong>Primitif connu :</strong> <span class=\"kw-bio\">biopsie</span> si <strong>métastase unique</strong> (exclure différentiel) — non systématique si autres métastases déjà documentées<br>\n              <strong>Primitif inconnu — métastase inaugurale :</strong>\n              <ol>\n                <li>Biopsier en <strong>priorité la tumeur primitive</strong> suspectée</li>\n                <li>Si inaccessible : biopsier le site métastatique le plus accessible (<span class=\"kw-clinique\">ganglion</span>, <span class=\"kw-clinique\">poumon</span>, <span class=\"kw-clinique\">foie</span>)</li>\n                <li>Si <span class=\"kw-bio\">biopsie</span> osseuse retenue : <span class=\"kw-clinique\"><strong>décalcification obligatoire</strong></span> pour l'<span class=\"kw-bio\">anatomopathologie</span></li>\n              </ol>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">⚠️ <strong><span class=\"kw-chiffre\">10 %</span> de primitif non retrouvé.</strong>\n        Au terme des explorations, le cancer primitif reste <strong>méconnu dans environ <span class=\"kw-chiffre\">10 %</span></strong> des métastases osseuses révélatrices. La stratégie thérapeutique se discute en <span class=\"kw-clinique\">RCP</span>.\n      </div>\n\n      <div class=\"callout callout-info\"><strong>Faux négatif scintigraphique — rappel.</strong>\n        Devant une <span class=\"kw-imagerie\">scintigraphie Tc<sup>99m</sup></span> normale + suspicion forte (<strong>myélome</strong>, métastases lytiques pures), recourir à <span class=\"kw-imagerie\">IRM corps entier</span> et/ou <span class=\"kw-imagerie\">TEP-FDG</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 292 — Diagnostic des cancers</em></p>","frequence":1}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.lecofer.org/item-cours-1-27-0.php","label":"Collège (COFER) — Item cours 1 27 0"}],"cards":[{"i":"0fce589c9b2f","n":307,"o":"307-1","u":"Définition","t":"Connaître les différents familles de tumeurs osseuses (primitive, secondaire)","q":"Quelle est la règle de fréquence des tumeurs osseuses malignes en fonction de l'âge ?","a":"<ul><li>Chez l'<strong>enfant, l'adolescent et l'adulte jeune</strong> : une tumeur osseuse maligne est le plus souvent <strong>primitive</strong>.</li><li>Chez l'<strong>adulte de plus de 50 ans</strong> : les <strong>métastases osseuses</strong> sont largement prédominantes.</li></ul>"},{"i":"6b7e759e893b","n":307,"o":"307-1","u":"Définition","t":"Connaître les différents familles de tumeurs osseuses (primitive, secondaire)","q":"Comment les tumeurs osseuses sont-elles classées selon leur origine cellulaire ?","a":"<p>Les tumeurs osseuses sont classées en deux grandes familles :</p><ul><li>Les <strong>tumeurs primitives</strong> : développées à partir des tissus de l'appareil ostéoarticulaire (os, cartilage, conjonctif, hématopoïétique, embryonnaire).</li><li>Les <strong>tumeurs secondaires</strong> (ou métastases osseuses) : issues d'un cancer primitif extra-osseux.</li></ul>"},{"i":"bb121f71b715","n":307,"o":"307-1","u":"Définition","t":"Connaître les différents familles de tumeurs osseuses (primitive, secondaire)","q":"Quels sont les principaux types histologiques de tumeurs osseuses primitives malignes selon leur tissu d'origine, et quelles sont les plus fréquentes ?","a":"<ul><li><strong>Tissu osseux</strong> : Ostéosarcome (le plus fréquent chez l'enfant).</li><li><strong>Tissu cartilagineux</strong> : Chondrosarcome (le plus fréquent chez l'adulte).</li><li><strong>Tissu conjonctif</strong> : Fibrosarcome, Histiocytofibrome malin.</li><li><strong>Tissu hématopoïétique</strong> : Plasmocytome, Lymphome osseux.</li><li><strong>Tissu embryonnaire</strong> : Sarcome d'Ewing (deuxième plus fréquent chez l'enfant), Chordome.</li></ul>"},{"i":"c4476fba0eba","n":307,"o":"307-1","u":"Définition","t":"Connaître les différents familles de tumeurs osseuses (primitive, secondaire)","q":"Quels sont les principaux facteurs de risque de tumeurs osseuses primitives ?","a":"<ul><li><strong>Radiothérapie antérieure</strong> : risque de cancer osseux 4 à 20 ans après.</li><li><strong>Maladie de Paget</strong> : risque de transformation en ostéosarcome.</li><li><strong>Infarctus osseux</strong> et <strong>fractures avec matériel orthopédique</strong> : risque accru de sarcome osseux secondaire.</li><li><strong>Syndrome de Li-Fraumeni</strong> (mutation germinale du gène p53) : risque d'ostéosarcome.</li><li><strong>Rétinoblastome familial</strong> (gène Rb) : risque d'ostéosarcome.</li><li><strong>Exostoses multiples</strong> et <strong>maladie d'Ollier</strong> (enchondromes multiples) : risque de chondrosarcome.</li></ul>"},{"i":"226472da5381","n":307,"o":"307-5","u":"Prise en charge","t":"Connaître les modalités d’orientation d’un patient vers une prise en charge spécialisée","q":"Qui doit idéalement réaliser la biopsie d'une tumeur osseuse primitive et quelles sont les modalités de réalisation et d'analyse ?","a":"<ul><li>La biopsie doit être réalisée idéalement par l'<strong>équipe chirurgicale</strong> qui réalisera ensuite l'exérèse carcinologique (pour assurer la <strong>continuité du trajet biopsique</strong>).</li><li>La voie peut être <strong>percutanée</strong> (sous contrôle radiographique ou scanographique) ou <strong>chirurgicale</strong>.</li><li>Les analyses incluent: <ul><li><strong>Histologique</strong> (avec décalcification et immunomarquage)</li><li><strong>Bactériologique</strong> (pour les germes banals et mycobactéries)</li><li><strong>Moléculaire</strong> (nécessite une biopsie à l'état frais pour FISH/PCR, notamment pour le sarcome d'Ewing).</li></ul></li><li>Une <strong>2<sup>e</sup> lecture histologique systématique</strong> par un expert d'un centre de référence est obligatoire.</li></ul>"},{"i":"6cb2871f861d","n":307,"o":"307-5","u":"Prise en charge","t":"Connaître les modalités d’orientation d’un patient vers une prise en charge spécialisée","q":"Pourquoi l'enclouage ou la mise en place de matériel orthopédique est-elle absolument proscrite en cas de fracture osseuse suspecte de tumeur primitive ?","a":"<p>L'enclouage ou la mise en place de matériel orthopédique (vis, plaque) est <strong>absolument proscrite</strong> car cela <strong>contamine l'os entier</strong> et expose à :</p><ul><li>Une <strong>rechute locale</strong>.</li><li>Une <strong>amputation ou désarticulation</strong> chez un patient qui aurait pu bénéficier d'un traitement conservateur du membre.</li></ul><p>Devant toute fracture suspecte, il faut privilégier une <strong>immobilisation simple</strong>, réaliser RX + IRM, et adresser le patient au réseau <strong>NETSARC+</strong>.</p>"},{"i":"9635ed3735c9","n":307,"o":"307-5","u":"Prise en charge","t":"Connaître les modalités d’orientation d’un patient vers une prise en charge spécialisée","q":"Quelle est la conduite à tenir initiale devant toute suspicion de tumeur osseuse primitive chez un patient ?","a":"<p>Devant toute suspicion de tumeur osseuse primitive, le patient doit être adressé <strong>sans délai à un centre spécialisé</strong>, comme un centre de référence du réseau <strong>NETSARC+</strong>.</p>"},{"i":"e0835a03ef8f","n":307,"o":"307-5","u":"Prise en charge","t":"Connaître les modalités d’orientation d’un patient vers une prise en charge spécialisée","q":"Quels sont les principes fondamentaux à respecter concernant la biopsie et le traitement face à une suspicion de tumeur osseuse primitive ?","a":"<ul><li><strong>Aucun traitement</strong> (et surtout aucun geste orthopédique tel qu'une ostéosynthèse) ne doit précéder le <strong>diagnostic anatomopathologique</strong>.</li><li>La biopsie est <strong>systématique</strong> avant tout traitement.</li><li>La décision de biopsie est <strong>multidisciplinaire</strong> en <strong>RCP</strong>.</li></ul>"},{"i":"088dc6b24526","n":307,"o":"307-6","u":"Epidémiologie","t":"Connaître les cancers qui sont le plus fréquemment responsable des métastases osseuses et les circonstances de découverte","q":"Quelle est la particularité radiologique du cancer de la prostate comme cause de métastases osseuses, et quelles sont les localisations osseuses les plus fréquentes de ces métastases ?","a":"<p>Les métastases osseuses du cancer de la prostate sont majoritairement <strong>ostéocondensantes</strong> (la seule métastase franchement condensante), bien qu'il existe des formes lytiques (25%).</p><p>Les métastases osseuses se localisent le plus fréquemment au niveau du <strong>rachis (lombaire puis thoracique)</strong>, du <strong>bassin</strong>, des <strong>côtes</strong>, du <strong>sternum</strong>, des <strong>fémurs</strong>, des <strong>humérus</strong> et du <strong>crâne</strong>.</p>"},{"i":"5690f8b47c4d","n":307,"o":"307-6","u":"Epidémiologie","t":"Connaître les cancers qui sont le plus fréquemment responsable des métastases osseuses et les circonstances de découverte","q":"Quels sont les cinq cancers primitifs majoritairement responsables des métastases osseuses chez l'adulte, et leur ordre de fréquence dans le cadre des métastases osseuses ?","a":"<p>Les cinq cancers primitifs les plus fréquents pourvoyeurs de métastases osseuses sont, par ordre de fréquence :</p><ul><li>le cancer du <strong>sein</strong></li><li>le cancer de la <strong>prostate</strong></li><li>le cancer du <strong>poumon</strong></li><li>le cancer du <strong>rein</strong></li><li>le cancer de la <strong>thyroïde</strong></li></ul><p>Un moyen mnémotechnique est <strong>PPRST</strong> (Prostate, Poumon, Rein, Sein, Thyroïde), bien que l'ordre de fréquence soit : <strong>sein > prostate > poumon > rein > thyroïde</strong>.</p>"},{"i":"f272e7457f45","n":307,"o":"307-6","u":"Epidémiologie","t":"Connaître les cancers qui sont le plus fréquemment responsable des métastases osseuses et les circonstances de découverte","q":"Quelles sont les circonstances de découverte d'une métastase osseuse, et quelle est la proportion de cas où le primitif reste inconnu ?","a":"Les circonstances de découverte d'une métastase osseuse sont :<ul><li>lors d'un <strong>bilan d'extension ou de surveillance</strong> d'un cancer déjà connu.</li><li>une <strong>découverte fortuite</strong> révélant la maladie cancéreuse (métastase osseuse inaugurale).</li><li>le bilan d'une <strong>hypercalcémie</strong>.</li><li>un <strong>syndrome rachidien majeur</strong> (douleurs rachidiennes inflammatoires, radiculalgie, troubles neurologiques par compression médullaire ou radiculaire).</li><li>une <strong>fracture pathologique</strong>, spontanée ou sur traumatisme minime.</li></ul><p>Dans environ <strong>10%</strong> des cas de métastases osseuses inaugurales, le cancer primitif reste <strong>méconnu</strong> après un bilan étiologique complet.</p>"}]};